function v8ServiceIntro(key){const d=V8[lang],p=d.pitches[key];return '<section class="section v8-service-intro"><div class="container v8-service-grid"><div><span class="eyebrow">'+esc(d.whyTitle)+'</span><h2 class="heading">'+esc(p[0])+'</h2><p class="lead">'+esc(service(key).intro)+'</p>'+navLink("#/contact?service="+key,d.introButton,"btn primary")+'</div><aside><span class="eyebrow">'+esc(d.receiveTitle)+'</span>'+p[1].map((x,i)=>'<p><span>0'+(i+1)+'</span>'+esc(x)+'</p>').join("")+'<small>'+esc(d.scopeNote)+'</small></aside></div></section>'}


const V9={"en":{"eyebrow":"THE NEW CHAPTER SIGNATURE SERVICE","headline":"We do more than explain.<br><em>We help organise the work.</em>","lead":"Your goals deserve more than a list of requirements. We can review your circumstances, prepare a service roadmap, organise relevant records and coordinate clearly agreed tasks. You always know what we are doing, what you need to do and what comes next.","promise":["We listen to your specific circumstances","We build a preparation plan around your goals","We help organise the documents and tasks","We guide the next steps within the agreed scope"],"serviceHeading":"What we can take care of for you","serviceLead":"This is where professional assistance becomes valuable. Explore the actual preparation and coordination work that can form part of your service.","serviceOutcome":"Your preparation portfolio","serviceOutcomeLead":"A useful set of working documents, not simply verbal advice.","deliverables":[["Case overview","A concise summary of your goals, circumstances and priorities."],["Personal roadmap","Practical preparation stages, responsibilities and relevant dependencies."],["Document register","An organised checklist of received and outstanding records."],["Action and follow-up list","A clear record of the next tasks and agreed preparation milestones."]],"serviceScope":"Examples of proposed service deliverables. Your quotation will specify which items New Chapter undertakes. Applications and decisions remain subject to the appropriate official processes.","journeyEyebrow":"A MORE PERSONAL SERVICE EXPERIENCE","journeyTitle":"From your first conversation<br><em>to your next steps.</em>","journeyLead":"A properly organised engagement should feel straightforward and personal at every stage.","journey":[["01","Understand your situation","We discuss your goals, circumstances, concerns and the preparation required."],["02","Receive a clear proposal","You see the service scope, responsibilities, fees and included deliverables before engaging."],["03","Create your roadmap","We organise the relevant preparation steps, documents and action owners."],["04","Prepare and coordinate","We work on the agreed tasks and help organise follow-ups with relevant parties where appropriate."],["05","Review what comes next","We confirm completed work, outstanding items and the next actions for you."]],"packagesEyebrow":"CHOOSE YOUR LEVEL OF SUPPORT","packagesTitle":"Professional support<br><em>on your terms.</em>","packagesLead":"Some customers want expert direction. Others prefer help preparing their application or coordinating a wider family journey. Each level would be quoted according to its confirmed scope.","packages":[["ADVISORY","New Chapter Advisory","A focused consultation to understand your options and the preparation needed.",["Focused discussion about your circumstances","Relevant requirements to investigate","Written preparation priorities and next steps"]],["APPLICATION SUPPORT","New Chapter Application Care","Practical assistance with an individual education or immigration application.",["Everything agreed in the consultation scope","Personalised document checklist and record organisation","Application-information preparation support","Agreed follow-up assistance"]],["COMPREHENSIVE","New Chapter Concierge","A coordinated service for families with connected education, immigration and relocation needs.",["Individual family preparation roadmap","School and accompanying-family planning where relevant","Document and service-provider coordination within scope","Agreed progress communication and practical relocation planning"]]],"packageNote":"These are proposed service levels. Availability, deliverables and fees will be confirmed in a formal quotation. No packages can be purchased online yet.","packageAction":"Explore consultation","whyUsTitle":"What makes the service different","whyUsText":"We connect the details that matter to your family or application instead of simply directing you to a government website.","detailNextEyebrow":"YOUR NEXT CHAPTER STARTS WITH A PLAN","detailNextTitle":"You bring the goal.<br><em>We help organise the preparation.</em>","detailNextText":"Tell us which service you are exploring. We can discuss a suitable scope and outline the next steps before any engagement.","more":{"education":[["Prepare a school comparison","Bring together relevant options, admission requirements, location and cost considerations in a format parents can compare."],["Organise parent-school communication","Help draft enquiries and coordinate agreed communications without implying a special admission relationship."],["Track preparation milestones","Keep a checklist of the assessment, records and admissions steps that apply to the chosen schools."],["Prepare an arrival and school-start checklist","Help the family organise the tasks involved in the child's transition to Singapore."]],"parent":[["Map the child's and parent's separate requirements","Make clear which actions concern the child's schooling and which concern the accompanying parent's stay."],["Organise sponsor-related preparation","Provide an action checklist for the eligible local sponsor and family, where sponsorship is required."],["Coordinate supporting records","Help prepare the relevant family relationship, identity and other records as required."],["Build an accompanying-parent arrival plan","Prepare practical next steps covering the family's intended arrival and living arrangements."]],"family":[["Compare relocation priorities","Prepare a practical comparison of neighbourhood, housing research, transport and school considerations."],["Coordinate document-related services","Help organise translation or certification arrangements with suitable providers when agreed."],["Prepare a family action register","Track what each adult, school or sponsor needs to do during preparation."],["Create a settling-in checklist","Organise the practical tasks the family can address before and after arrival."]],"pr":[["Build a personal document inventory","Organise the supporting records relevant to your applicant category, including what remains outstanding."],["Check factual consistency","Review documents for missing information and inconsistencies without inventing or changing facts."],["Prepare a submission-ready organisation plan","Group files, form information and customer-confirmation tasks according to the official process."],["Support agreed follow-up preparation","Help organise documents requested through official channels after submission when covered by the engagement."]],"citizenship":[["Prepare a personal-document inventory","Create an orderly record of applicable family, identity, education and employment documents."],["Identify key declarations and responsibilities","Explain which important application statements and official obligations need the applicant's attention."],["Organise the application-information review","Help the applicant check factual completeness and consistency before authorised submission."],["Prepare the follow-up action plan","Explain how to organise official correspondence and additional-document preparation where needed."]],"documents":[["Create an organised document register","Track which records are received, missing, expired or require clarification."],["Prepare the translation brief","Identify the intended document use and relevant translation or certification requirements."],["Coordinate agreed document providers","Assist with administrative coordination where outside services are necessary and appropriate."],["Provide a final preparation checklist","Summarise file organisation, remaining actions and the party responsible for each."]]}},"vi":{"eyebrow":"DỊCH VỤ ĐỒNG HÀNH NEW CHAPTER","headline":"Không chỉ tư vấn.<br><em>Chúng tôi giúp bạn chuẩn bị từng bước.</em>","lead":"Bạn không chỉ cần đọc các điều kiện. Bạn cần người giúp tìm hiểu hoàn cảnh, lập kế hoạch, sắp xếp hồ sơ và phối hợp những công việc đã thống nhất. New Chapter đề xuất một trải nghiệm dịch vụ rõ ràng, có trách nhiệm và phù hợp với từng mục tiêu.","promise":["Lắng nghe hoàn cảnh và mục tiêu riêng của bạn","Lập kế hoạch chuẩn bị phù hợp","Hỗ trợ sắp xếp giấy tờ và công việc","Hướng dẫn từng bước trong phạm vi đã thống nhất"],"serviceHeading":"Những công việc chúng tôi có thể hỗ trợ bạn","serviceLead":"Đây là giá trị của dịch vụ chuyên nghiệp: những việc chuẩn bị và phối hợp cụ thể, được tổ chức theo nhu cầu của bạn.","serviceOutcome":"Bộ tài liệu chuẩn bị dành cho bạn","serviceOutcomeLead":"Những tài liệu và công việc cụ thể, không chỉ là lời tư vấn.","deliverables":[["Tổng quan hồ sơ","Tóm tắt mục tiêu, hoàn cảnh và những nội dung ưu tiên."],["Lộ trình riêng","Các giai đoạn chuẩn bị, trách nhiệm và những việc liên quan."],["Danh mục giấy tờ","Checklist giấy tờ đã có, còn thiếu và cần bổ sung."],["Danh sách việc tiếp theo","Các đầu việc và mốc tiến độ được thống nhất."]],"serviceScope":"Đây là ví dụ về nội dung dịch vụ dự kiến. Báo giá sẽ xác nhận chính xác những công việc New Chapter đảm nhận. Việc xét duyệt thuộc quy trình chính thức.","journeyEyebrow":"TRẢI NGHIỆM DỊCH VỤ CÁ NHÂN","journeyTitle":"Từ buổi trao đổi đầu tiên<br><em>đến những bước tiếp theo.</em>","journeyLead":"Một dịch vụ chuyên nghiệp cần giúp bạn hiểu rõ quá trình hợp tác ngay từ đầu.","journey":[["01","Tìm hiểu hoàn cảnh","Trao đổi về mục tiêu, tình hình gia đình và những nội dung cần chuẩn bị."],["02","Nhận đề xuất rõ ràng","Biết phạm vi dịch vụ, trách nhiệm, chi phí và tài liệu bàn giao trước khi quyết định."],["03","Lập lộ trình chuẩn bị","Sắp xếp các bước, giấy tờ và người phụ trách từng công việc."],["04","Chuẩn bị và phối hợp","Hỗ trợ những đầu việc đã thống nhất và phối hợp với các bên liên quan khi phù hợp."],["05","Rà soát bước tiếp theo","Tổng kết công việc đã thực hiện, những nội dung còn thiếu và hướng tiếp tục."]],"packagesEyebrow":"CHỌN MỨC HỖ TRỢ PHÙ HỢP","packagesTitle":"Dịch vụ chuyên nghiệp<br><em>theo nhu cầu của bạn.</em>","packagesLead":"Có khách hàng chỉ cần định hướng. Có gia đình muốn được hỗ trợ hồ sơ hoặc phối hợp toàn bộ các công việc liên quan. Phạm vi sẽ được báo giá rõ ràng.","packages":[["TƯ VẤN","New Chapter Advisory","Buổi tư vấn tập trung vào hoàn cảnh, lựa chọn và việc cần chuẩn bị.",["Trao đổi về tình hình và mục tiêu","Điều kiện cần tìm hiểu và xác minh","Tóm tắt những việc ưu tiên và bước tiếp theo"]],["HỖ TRỢ HỒ SƠ","New Chapter Application Care","Hỗ trợ thực tế khi chuẩn bị hồ sơ học tập hoặc di trú.",["Các nội dung đã thống nhất trong gói tư vấn","Checklist giấy tờ riêng và sắp xếp tài liệu","Hỗ trợ chuẩn bị thông tin hồ sơ","Hỗ trợ bổ sung trong phạm vi thỏa thuận"]],["TOÀN DIỆN","New Chapter Concierge","Dịch vụ phối hợp cho gia đình có nhu cầu học tập, di trú và chuyển đến Singapore.",["Lộ trình chuẩn bị riêng cho gia đình","Kế hoạch học tập và người thân đi cùng khi liên quan","Phối hợp tài liệu và bên cung cấp dịch vụ trong phạm vi đã thống nhất","Cập nhật công việc và hỗ trợ kế hoạch ổn định cuộc sống"]]],"packageNote":"Đây là các mức dịch vụ dự kiến. Nội dung, khả năng cung cấp và chi phí sẽ được xác nhận trong báo giá. Website chưa nhận thanh toán trực tuyến.","packageAction":"Tìm hiểu tư vấn","whyUsTitle":"Giá trị của sự hỗ trợ","whyUsText":"Chúng tôi kết nối các công việc liên quan đến gia đình và hồ sơ, thay vì chỉ chuyển bạn đến trang thông tin chính thức.","detailNextEyebrow":"BẮT ĐẦU VỚI MỘT KẾ HOẠCH","detailNextTitle":"Bạn có mục tiêu.<br><em>Chúng tôi giúp chuẩn bị rõ ràng.</em>","detailNextText":"Chọn dịch vụ đang quan tâm. Hai bên có thể trao đổi về phạm vi hỗ trợ và bước tiếp theo trước khi hợp tác.","more":{"education":[["Lập bảng so sánh trường học","Tập hợp các lựa chọn phù hợp để phụ huynh so sánh điều kiện tuyển sinh, vị trí và ngân sách."],["Hỗ trợ liên hệ với trường","Giúp soạn câu hỏi và phối hợp liên hệ theo phạm vi thỏa thuận, không tự nhận có quan hệ tuyển sinh đặc biệt."],["Theo dõi mốc chuẩn bị","Lập checklist cho các kỳ đánh giá, giấy tờ và bước tuyển sinh liên quan."],["Chuẩn bị ngày nhập học","Sắp xếp danh sách công việc cho quá trình chuyển đến và bắt đầu học tại Singapore."]],"parent":[["Phân biệt thủ tục của con và phụ huynh","Làm rõ các đầu việc liên quan đến việc học của con và diện lưu trú của mẹ hoặc người đi cùng."],["Chuẩn bị nhiệm vụ của người bảo lãnh","Lập checklist cho người bảo lãnh địa phương đủ điều kiện khi cần."],["Phối hợp giấy tờ gia đình","Sắp xếp hồ sơ quan hệ gia đình, nhân thân và những tài liệu được yêu cầu."],["Lập kế hoạch chuyển đến","Chuẩn bị các việc thực tế về thời gian đến và sinh hoạt của gia đình."]],"family":[["So sánh nhu cầu chuyển đến","Lập bảng tìm hiểu khu vực sinh sống, giao thông, nhà ở và trường học."],["Phối hợp dịch vụ giấy tờ","Hỗ trợ sắp xếp dịch thuật hoặc chứng nhận phù hợp khi có trong hợp đồng."],["Tạo danh sách công việc gia đình","Theo dõi phần việc của từng thành viên, trường học hoặc người bảo lãnh."],["Checklist ổn định cuộc sống","Tổ chức những việc cần chuẩn bị trước và sau khi đến Singapore."]],"pr":[["Lập danh mục giấy tờ riêng","Sắp xếp hồ sơ theo diện đăng ký và đánh dấu những tài liệu cần bổ sung."],["Kiểm tra sự thống nhất thông tin","Rà soát thiếu sót hoặc khác biệt giữa các tài liệu mà không sửa hoặc tạo thông tin sai."],["Tổ chức hồ sơ trước khi nộp","Sắp xếp file, thông tin cần xác nhận và bước chuẩn bị theo quy trình chính thức."],["Hỗ trợ chuẩn bị bổ sung","Giúp tổ chức giấy tờ được yêu cầu qua kênh chính thức nếu có trong phạm vi dịch vụ."]],"citizenship":[["Lập danh mục tài liệu cá nhân","Sắp xếp giấy tờ gia đình, nhân thân, học vấn và việc làm phù hợp."],["Làm rõ nghĩa vụ và khai báo","Giúp hiểu những nội dung quan trọng người đăng ký cần lưu ý."],["Rà soát thông tin hồ sơ","Hỗ trợ kiểm tra độ đầy đủ và nhất quán trước khi người có thẩm quyền nộp đơn."],["Lập kế hoạch theo dõi","Hướng dẫn tổ chức thông báo chính thức và giấy tờ bổ sung nếu cần."]],"documents":[["Lập danh mục giấy tờ","Phân biệt giấy tờ đã có, còn thiếu, hết hạn hoặc cần xác minh."],["Chuẩn bị yêu cầu dịch thuật","Xác định mục đích sử dụng và yêu cầu dịch thuật hoặc chứng nhận liên quan."],["Phối hợp bên cung cấp dịch vụ","Hỗ trợ phối hợp hành chính với đơn vị phù hợp khi cần."],["Checklist hoàn thiện hồ sơ","Tổng hợp file, các việc còn lại và người phụ trách."]]}}};
function v9Intro(){const x=V9[lang];return '<section class="section v9-intro" id="signature"><div class="container v9-intro-grid"><div><span class="eyebrow">'+esc(x.eyebrow)+'</span><h2 class="heading">'+x.headline+'</h2><p class="lead">'+esc(x.lead)+'</p>'+navLink("#/services",x.packageAction,"btn primary")+'</div><div class="v9-intro-steps">'+x.promise.map((item,i)=>'<div class="v9-intro-line"><span>0'+(i+1)+'</span><p>'+esc(item)+'</p></div>').join("")+'</div></div></section>'}
function v9Portfolio(){const x=V9[lang];return '<section class="section v9-portfolio"><div class="container"><div class="v9-portfolio-head"><span class="eyebrow">'+esc(x.serviceOutcome)+'</span><h2 class="heading">'+esc(x.serviceOutcome)+'</h2><p class="lead">'+esc(x.serviceOutcomeLead)+'</p></div><div class="v9-portfolio-grid">'+x.deliverables.map((it,i)=>'<article class="v9-portfolio-item"><span class="v9-portfolio-no">0'+(i+1)+' / NEW CHAPTER</span><div class="v9-file-illustration" aria-hidden="true"><span></span><span></span><span></span></div><h3>'+esc(it[0])+'</h3><p>'+esc(it[1])+'</p></article>').join("")+'</div><p class="v9-scope">'+esc(x.serviceScope)+'</p></div></section>'}
function v9Journey(){const x=V9[lang];return '<section class="section v9-journey" id="journey"><div class="container"><div class="v9-journey-heading"><span class="eyebrow">'+esc(x.journeyEyebrow)+'</span><h2 class="heading">'+x.journeyTitle+'</h2><p class="lead">'+esc(x.journeyLead)+'</p></div><div class="v9-journey-grid">'+x.journey.map(it=>'<article><span>'+esc(it[0])+'</span><h3>'+esc(it[1])+'</h3><p>'+esc(it[2])+'</p></article>').join("")+'</div></div></section>'}
function v9Packages(){const x=V9[lang];return '<section class="section v9-packages" id="offers"><div class="container"><div class="v9-package-heading"><span class="eyebrow">'+esc(x.packagesEyebrow)+'</span><h2 class="heading">'+x.packagesTitle+'</h2><p class="lead">'+esc(x.packagesLead)+'</p></div><div class="v9-package-grid">'+x.packages.map((p,i)=>'<article class="v9-package-card '+(i===2?'v9-featured':'')+'"><span class="v9-plan-label">'+esc(p[0])+'</span><h3>'+esc(p[1])+'</h3><p>'+esc(p[2])+'</p><div class="v9-package-list">'+p[3].map(a=>'<div><span aria-hidden="true">✓</span>'+esc(a)+'</div>').join("")+'</div>'+navLink("#/contact",x.packageAction,"btn")+'</article>').join("")+'</div><p class="v9-scope">'+esc(x.packageNote)+'</p></div></section>'}
function v9ExpandedService(key){const x=V9[lang],data=SERVICE_DEPTH[lang][key],more=x.more[key];const list=[...data.items,...more];return '<section class="section v9-service" id="what-we-do"><div class="container"><div class="v9-service-top"><span class="eyebrow">'+esc(x.eyebrow)+'</span><h2 class="heading">'+esc(x.serviceHeading)+'</h2><p class="lead">'+esc(x.serviceLead)+'</p></div><div class="v9-service-list">'+list.map((it,i)=>'<article class="v9-service-item"><span class="v9-service-num">'+String(i+1).padStart(2,"0")+'</span><div><h3>'+esc(it[0])+'</h3><p>'+esc(it[1])+'</p></div></article>').join("")+'</div><div class="v9-service-summary"><span>'+esc(x.serviceOutcome)+'</span><h3>'+esc(data.outcome)+'</h3><p>'+esc(x.serviceScope)+'</p></div></div></section>'}
function v9ServiceClose(key){const x=V9[lang];return '<section class="section v9-service-close"><div class="container"><span class="eyebrow">'+esc(x.detailNextEyebrow)+'</span><h2 class="heading">'+x.detailNextTitle+'</h2><p>'+esc(x.detailNextText)+'</p>'+navLink("#/contact?service="+key,x.packageAction,"btn primary")+'</div></section>'}


const V10={
en:{headline:"Singapore PR, Citizenship & Education Services",summary:"Professional assistance with Singapore Permanent Residency, Citizenship, school admission, Student's Pass, accompanying-parent LTVP and family relocation.",serviceTitle:"Our Singapore Immigration & Education Services",serviceIntro:"Choose the service you need. See the actual work New Chapter can assist with and the steps involved.",whyTitle:"Why Engage New Chapter?",whyIntro:"Clear scope. Personal preparation. Organised documents. Practical service coordination.",workTitle:"What New Chapter Does for You",workIntro:"Our services focus on useful preparation work, not simply explaining government websites.",processTitle:"Our Application Assistance Process",aboutTitle:"About New Chapter",aboutText:"New Chapter is a Singapore private consultancy focused on education, immigration application preparation and family relocation guidance. We aim to provide clearly scoped, organised and practical assistance.",faqTitle:"Frequently Asked Questions",exampleTitle:"How Our Service Could Work",exampleText:"Illustrative scenario: A family exploring school admission and accompanying-parent arrangements. A proposed service could include school research, admission-document preparation, Student's Pass guidance, a separate parent-LTVP requirements checklist and coordinated relocation tasks. This is a service illustration, not a real client testimonial.",emailTitle:"Email New Chapter",emailText:"Choose a service below. Our official business email address has not yet been configured, so online enquiries cannot be sent from this website.",emailPending:"Official company email address coming soon",contact:"Email Enquiry",services:[["Singapore PR","PR application preparation and supporting-document assistance","pr"],["Singapore Citizenship","Citizenship application preparation and document organisation","citizenship"],["School Admission","Singapore school options and admission application support","education"],["Student's Pass","Student immigration application preparation","student"],["Accompanying-Parent LTVP","Application support for eligible parents or grandparents accompanying students","parent"],["Family Relocation","Family immigration and moving preparation assistance","family"]],why:[["Personalised assistance","We review the relevant circumstances and application category."],["Document organisation","We help build a tailored checklist and prepare supporting materials."],["Transparent service scope","You understand the work, responsibilities and fees before engagement."],["Education and family support","We help coordinate related schooling, student and parent preparation where appropriate."]],process:[["01","Service enquiry","Choose PR, Citizenship, Education, Student's Pass, LTVP or Relocation."],["02","Consultation","Discuss relevant circumstances and preparation requirements."],["03","Quotation","Receive the agreed scope, deliverables, fees and terms."],["04","Preparation","We carry out the specified document and application support work."],["05","Follow-up","We help organise the agreed next steps and outstanding items."]],faq:[["Can New Chapter help prepare my application?","Services may include consultation, tailored checklists, accurate application-information preparation, organisation of supporting records and agreed follow-up tasks."],["How are service fees determined?","Fees are quoted for the agreed work scope. Any applicable government application fees should be shown separately."],["Will New Chapter submit the application for me?","The relevant official process determines who may submit and make declarations. We can guide the permitted preparation steps."],["Can a mother accompany a child studying in Singapore?","Certain qualifying students may have an eligible parent or grandparent apply under an applicable LTVP route, subject to the specific ICA requirements and local sponsorship conditions."],["Can you guarantee a PR or citizenship outcome?","No consultancy controls ICA's decisions. The service focuses on accurate, organised preparation."],["Can you help with schools and Student's Pass?","School-options research, admission preparation and relevant pass-document guidance can be included within an agreed scope. Schools decide admissions."]]},
vi:{headline:"Dịch vụ PR, Quốc tịch & Giáo dục Singapore",summary:"Hỗ trợ chuyên nghiệp về hồ sơ PR, Quốc tịch Singapore, tuyển sinh, Student's Pass, LTVP cho phụ huynh đi cùng học sinh và gia đình chuyển đến Singapore.",serviceTitle:"Dịch vụ Di trú & Giáo dục Singapore",serviceIntro:"Chọn dịch vụ bạn cần để xem công việc New Chapter có thể hỗ trợ và các bước chuẩn bị.",whyTitle:"Vì sao chọn New Chapter?",whyIntro:"Phạm vi rõ ràng. Hỗ trợ cá nhân. Hồ sơ có tổ chức. Phối hợp công việc thực tế.",workTitle:"New Chapter làm gì cho bạn?",workIntro:"Dịch vụ tập trung vào những việc chuẩn bị hữu ích, không chỉ giải thích trang thông tin chính thức.",processTitle:"Quy trình hỗ trợ hồ sơ",aboutTitle:"Về New Chapter",aboutText:"New Chapter là công ty tư vấn tư nhân tại Singapore, chuyên hỗ trợ chuẩn bị hồ sơ giáo dục, di trú và kế hoạch gia đình chuyển đến Singapore. Chúng tôi chú trọng phạm vi rõ ràng và công việc thực tế.",faqTitle:"Câu hỏi thường gặp",exampleTitle:"Ví dụ cách chúng tôi hỗ trợ",exampleText:"Tình huống minh họa: Gia đình tìm hiểu tuyển sinh và người thân đi cùng học sinh. Dịch vụ dự kiến có thể gồm nghiên cứu trường, chuẩn bị hồ sơ tuyển sinh, hướng dẫn Student's Pass, checklist LTVP riêng cho phụ huynh và việc chuyển đến. Đây không phải lời chứng thực của khách hàng thực tế.",emailTitle:"Liên hệ New Chapter qua email",emailText:"Chọn dịch vụ bên dưới. Email chính thức của công ty chưa được cấu hình nên website hiện chưa thể nhận yêu cầu trực tuyến.",emailPending:"Email chính thức của công ty sẽ được bổ sung",contact:"Liên hệ qua email",services:[["Hồ sơ PR Singapore","Hỗ trợ chuẩn bị đơn PR và tài liệu liên quan","pr"],["Quốc tịch Singapore","Hỗ trợ chuẩn bị hồ sơ và giấy tờ quốc tịch","citizenship"],["Tuyển sinh tại Singapore","Tìm hiểu trường và chuẩn bị hồ sơ tuyển sinh","education"],["Student's Pass","Hỗ trợ chuẩn bị đơn lưu trú cho học sinh","student"],["LTVP cho phụ huynh đi cùng","Hỗ trợ cha mẹ hoặc ông bà đủ điều kiện đi cùng học sinh","parent"],["Gia đình chuyển đến Singapore","Hỗ trợ chuẩn bị hồ sơ và các việc chuyển đến","family"]],why:[["Phù hợp hoàn cảnh","Xem xét hoàn cảnh và diện đăng ký liên quan."],["Sắp xếp giấy tờ","Hỗ trợ checklist riêng và chuẩn bị tài liệu."],["Phạm vi minh bạch","Thống nhất công việc, trách nhiệm và phí trước khi hợp tác."],["Học tập và gia đình","Phối hợp việc chuẩn bị của học sinh và phụ huynh khi phù hợp."]],process:[["01","Yêu cầu dịch vụ","Chọn PR, Quốc tịch, Tuyển sinh, Student's Pass, LTVP hoặc Chuyển đến."],["02","Trao đổi ban đầu","Tìm hiểu hoàn cảnh và yêu cầu chuẩn bị."],["03","Báo giá","Nhận phạm vi, tài liệu bàn giao, phí và điều khoản."],["04","Chuẩn bị hồ sơ","Thực hiện công việc hỗ trợ đã thống nhất."],["05","Theo dõi","Phối hợp những việc còn lại và bước tiếp theo."]],faq:[["New Chapter có hỗ trợ chuẩn bị hồ sơ không?","Dịch vụ có thể gồm tư vấn, checklist riêng, chuẩn bị thông tin chính xác, sắp xếp tài liệu và phối hợp công việc đã thống nhất."],["Phí dịch vụ được tính như thế nào?","Báo giá theo phạm vi công việc. Phí chính thức của cơ quan nhà nước được tính riêng."],["New Chapter có nộp đơn thay không?","Quy trình chính thức quy định người có quyền nộp và khai báo. Chúng tôi hỗ trợ chuẩn bị theo phạm vi cho phép."],["Mẹ có thể đi cùng con học ở Singapore không?","Cha mẹ hoặc ông bà của một số học sinh đủ điều kiện có thể xin LTVP theo diện phù hợp, tùy điều kiện ICA và người bảo lãnh địa phương."],["Có đảm bảo được PR hoặc Quốc tịch không?","ICA quyết định việc xét duyệt. Dịch vụ tập trung vào việc chuẩn bị chính xác và có tổ chức."],["Có hỗ trợ trường học và Student's Pass không?","Có thể hỗ trợ nghiên cứu trường, chuẩn bị hồ sơ tuyển sinh và giấy phép theo phạm vi thống nhất. Trường quyết định việc tuyển sinh."]]}
};
function v10ServiceCards(){const d=V10[lang];return '<section class="section v10-services" id="services"><div class="container"><span class="eyebrow">NEW CHAPTER · SERVICES</span><h2 class="heading">'+esc(d.serviceTitle)+'</h2><p class="lead">'+esc(d.serviceIntro)+'</p><div class="v10-card-grid">'+d.services.map((it,i)=>'<a class="v10-service-card" href="#/service/'+it[2]+'"><small>0'+(i+1)+' / NEW CHAPTER</small><h3>'+esc(it[0])+'</h3><p>'+esc(it[1])+'</p><span aria-hidden="true">↗</span></a>').join("")+'</div>'+navLink("#/service/documents",lang==="vi"?"Hỗ trợ hồ sơ & dịch thuật":"Document & translation support","text-link")+'</div></section>'}
function v10Why(){const d=V10[lang];return '<section class="section v10-why" id="why"><div class="container"><span class="eyebrow">WHY NEW CHAPTER</span><h2 class="heading">'+esc(d.whyTitle)+'</h2><p class="lead">'+esc(d.whyIntro)+'</p><div class="v10-why-grid">'+d.why.map((x,i)=>'<article><span>0'+(i+1)+'</span><h3>'+esc(x[0])+'</h3><p>'+esc(x[1])+'</p></article>').join("")+'</div></div></section>'}
function v10Process(){const d=V10[lang];return '<section class="section v10-process" id="process"><div class="container"><span class="eyebrow">HOW WE WORK</span><h2 class="heading">'+esc(d.processTitle)+'</h2><div class="v10-process-grid">'+d.process.map(x=>'<article><b>'+esc(x[0])+'</b><h3>'+esc(x[1])+'</h3><p>'+esc(x[2])+'</p></article>').join("")+'</div></div></section>'}
function v10Faq(key){const d=V10[lang];const rows=key==="parent"?[d.faq[3],...d.faq.slice(0,3)]:key==="pr"||key==="citizenship"?[d.faq[0],d.faq[4],...d.faq.slice(1,3)]:key==="education"||key==="student"?[d.faq[5],d.faq[3],...d.faq.slice(0,2)]:d.faq;return '<section class="section v10-faq" id="faq"><div class="container"><h2 class="heading">'+esc(d.faqTitle)+'</h2><div class="v10-faq-list">'+rows.map(a=>'<details><summary>'+esc(a[0])+'</summary><p>'+esc(a[1])+'</p></details>').join("")+'</div></div></section>'}
function v10About(){const d=V10[lang];return '<section class="section v10-about" id="about"><div class="container v10-about-grid"><div>'+img("family")+'</div><div><span class="eyebrow">NEW CHAPTER</span><h2 class="heading">'+esc(d.aboutTitle)+'</h2><p class="lead">'+esc(d.aboutText)+'</p></div></div></section>'}
function v10Example(){const d=V10[lang];return '<section class="section v10-example"><div class="container"><span class="eyebrow">'+(lang==="vi"?"VÍ DỤ MINH HỌA":"ILLUSTRATIVE SERVICE EXAMPLE")+'</span><h2 class="heading">'+esc(d.exampleTitle)+'</h2><p class="lead">'+esc(d.exampleText)+'</p></div></section>'}
function v10Hero(){const d=V10[lang];return '<section class="hero v10-hero">'+img("hero",true)+'<div class="container hero-inner"><div class="hero-copy"><span class="eyebrow">'+(lang==="vi"?"TƯ VẤN DI TRÚ & GIÁO DỤC SINGAPORE":"SINGAPORE IMMIGRATION & EDUCATION CONSULTANCY")+'</span><h1>'+d.headline+'</h1><p>'+esc(d.summary)+'</p><div class="hero-actions">'+navLink("#/services",lang==="vi"?"Xem dịch vụ":"View Our Services","btn primary")+navLink("#/contact",d.contact,"btn light")+'</div></div></div></section>'}
function v10Homepage(){document.title="NEW CHAPTER | "+V10[lang].headline.replace(/<[^>]+>/g,"");return v10Hero()+v10ServiceCards()+v10Why()+v10Process()+v9Portfolio()+v10Example()+v10Faq()+v10About()+'<section class="section v10-last"><div class="container"><h2>'+esc(V10[lang].emailTitle)+'</h2>'+navLink("#/contact",V10[lang].contact,"btn primary")+'</div></section>'}
