function v10Student(){const d=V10[lang];return '<section class="section v10-student"><div class="container"><span class="eyebrow">STUDENT’S PASS</span><h1 class="heading">'+esc(d.services[3][0])+'</h1><p class="lead">'+esc(d.services[3][1])+'</p></div></section>'+v10Process()+v10Faq("student")+'<section class="section v10-last"><div class="container">'+navLink("#/contact?service=student",d.contact,"btn primary")+'</div></section>'}
function v10Details(key){const d=V10[lang],item=d.services.find(p=>p[2]===key);document.title=(item?item[0]:service(key).title)+" | NEW CHAPTER";return '<section class="detail-hero"><div class="container"><span class="eyebrow">NEW CHAPTER · SERVICES</span><h1>'+esc(item?item[0]:service(key).title)+'</h1><p class="lead">'+esc(service(key).intro)+'</p>'+navLink("#/contact?service="+key,d.contact,"btn primary")+'</div></section>'+v9ExpandedService(key)+v9Portfolio()+v10Process()+v10Faq(key)+'<section class="section v10-last"><div class="container">'+navLink("#/contact?service="+key,d.contact,"btn primary")+'</div></section>'}

