const SERVICE_DEPTH={"en":{"education":{"headline":"From choosing a school to preparing for your child's arrival.","intro":"School applications, pass requirements and family arrangements should be planned together. New Chapter can help organise the decisions, paperwork and next steps that fit your child's circumstances.","items":[["Understand your child's starting point","Discuss age, current school level, preferred curriculum, budget, likely entry period and the type of Singapore school you are considering."],["Build a school-options shortlist","Explain relevant school categories, admissions routes and the factors families should compare before choosing where to apply."],["Prepare for admissions","Identify applicable application windows, school-requested records, possible assessments and the responsibilities of parents and schools."],["Organise Student's Pass preparation","Review whether a Student's Pass may be required, list relevant supporting records and explain the official steps that apply to the chosen education route."],["Plan accompanying-family arrangements","Where relevant, explain that accompanying-parent arrangements have separate conditions and help the family understand sponsorship and relocation considerations."],["Coordinate the move","Help structure the preparation of accommodation research, arrival timing, school-start essentials and next steps within the agreed service scope."]],"outcome":"A tailored education-preparation roadmap, relevant school and admission checklist, pass-preparation guidance and clear family responsibilities."},"parent":{"headline":"When your child studies in Singapore, your own arrangements matter too.","intro":"Families need to understand whether an accompanying-parent route applies and what has to be arranged separately from a child's admission and Student's Pass.","items":[["Review the family's circumstances","Understand the child's school and immigration position, who wishes to accompany the child, and the family's proposed living arrangements."],["Clarify the applicable LTVP route","Explain the eligibility factors relevant to a parent or grandparent accompanying a qualifying student, without assuming every family qualifies."],["Understand local sponsorship","Outline the need for an eligible local sponsor where required and identify the sponsor-related information that may need preparation."],["Prepare family-relationship documents","Organise applicable passports, birth certificates, proof of relationship and other supporting documents specified by the official process."],["Coordinate the application sequence","Help families understand which steps depend on school admission, the child's status, sponsorship or immigration processing."],["Prepare for everyday life","Within an agreed relocation scope, organise a practical checklist for accommodation, arrival, school routines and family needs."]],"outcome":"An accompanying-parent preparation plan, eligibility questions to resolve, sponsor checklist and organised next steps for the family."},"family":{"headline":"A move to Singapore involves more than an immigration application.","intro":"Relocating as a family means coordinating a legal route with schooling, accommodation, timing, finances and practical life decisions.","items":[["Map each family member's needs","Identify the purpose of the move, each person's intended stay and the family relationships relevant to available immigration routes."],["Identify official pathways to investigate","Help distinguish possible family-related passes and the specific eligibility questions that must be checked before planning around them."],["Organise supporting records","Prepare a checklist for identity, relationship, financial and other documents appropriate to the chosen route."],["Build a relocation timeline","List decisions and dependencies involving application readiness, school terms, housing research and travel planning."],["Prepare for settling in","Develop practical checklists around accommodation research, transport, schooling and common arrival arrangements."],["Keep responsibilities clear","Record which activities belong to the family, a sponsor, an educational institution and New Chapter under the agreed engagement."]],"outcome":"A coordinated family-preparation roadmap covering relevant pass questions, documents, timeline and practical relocation priorities."},"pr":{"headline":"Prepare your Singapore PR application with structure and attention to detail.","intro":"Permanent Residency is an important decision. New Chapter's value is to help eligible applicants organise the preparation process, understand the relevant ICA category and present their information accurately and consistently.","items":[["Understand your eligibility category","Review the type of PR application being considered, such as a family, employment, student or investment-related route, and identify the official conditions to verify."],["Review your application circumstances","Discuss relevant personal, family, education, employment and residence details to establish which supporting information may be needed."],["Create a document checklist","Set out the identity, civil, education, employment and other records relevant to the official checklist for the selected applicant category."],["Organise records and consistency","Help check document completeness, naming and the consistency of information supplied across supporting records, without inventing or altering facts."],["Prepare for the online application","Explain the relevant application sequence, supporting-file preparation and applicant responsibilities for submission and fees."],["Plan after submission","Clarify the official communication process, potential follow-up document requests and the steps to monitor while awaiting a decision."]],"outcome":"A category-specific PR preparation plan, personalised document checklist, organised records and clearly explained submission responsibilities."},"citizenship":{"headline":"Take your citizenship preparation seriously, with a clear plan.","intro":"Singapore Citizenship applications can involve eligibility, family circumstances, supporting records and significant responsibilities. We can help organise the preparation for the route that applies.","items":[["Identify the relevant application route","Explore the citizenship category being considered and the qualifying conditions that must be checked against ICA guidance."],["Understand family circumstances","Review the applicable details of the applicant and, where relevant, spouse, parent or child relationships for document planning."],["Build a tailored checklist","Identify identity, civil, education, employment and other supporting records relevant to the selected route."],["Prepare your information carefully","Help structure supporting records and ensure the details presented are accurate and consistent with the official process."],["Explain key responsibilities","Draw attention to significant obligations and official requirements that may affect an applicant or family, including where independent advice may be needed."],["Plan the official next steps","Outline the submission, communication and follow-up process in a way the applicant can understand and organise."]],"outcome":"A citizenship application-preparation roadmap, appropriate supporting-document checklist and understanding of the responsibilities and next steps."},"documents":{"headline":"Make complex paperwork easier to manage.","intro":"Different education and immigration processes request different documents. We help structure the preparation so you can see what is ready, what is missing and what may need translation or certification.","items":[["Identify the intended application","Understand the school, immigration or relocation process that determines which records are needed."],["Produce a document inventory","Create a practical list of required and supporting records relevant to the selected procedure."],["Flag gaps and inconsistencies","Help identify missing pages, expired documents or differences in names, dates and other information that need clarification."],["Clarify translation needs","Explain when an official translation or certification may be required and coordinate appropriate providers where this forms part of the service."],["Organise files for submission","Help customers group, name and prepare copies in the format required by the relevant process."],["Prepare a completion checklist","Summarise outstanding items, ownership and the next action before the application can move forward."]],"outcome":"An organised document inventory, outstanding-items checklist and agreed coordination for translation or certification needs."}},"vi":{"education":{"headline":"Từ lựa chọn trường đến chuẩn bị cho ngày con bắt đầu học.","intro":"Việc tuyển sinh, giấy phép và kế hoạch của gia đình cần được chuẩn bị đồng bộ. New Chapter có thể giúp bạn sắp xếp các quyết định, giấy tờ và bước tiếp theo phù hợp với con.","items":[["Hiểu nhu cầu học tập của con","Trao đổi về độ tuổi, lớp đang học, chương trình mong muốn, ngân sách, thời gian nhập học và loại trường đang cân nhắc."],["Xác định lựa chọn trường","Giải thích các nhóm trường, hình thức tuyển sinh có liên quan và những tiêu chí gia đình nên so sánh."],["Chuẩn bị hồ sơ tuyển sinh","Xác định thời điểm nộp hồ sơ, giấy tờ nhà trường yêu cầu, các kỳ đánh giá có thể có và trách nhiệm của phụ huynh."],["Chuẩn bị Student's Pass","Tìm hiểu khi nào cần Student's Pass, giấy tờ liên quan và các bước chính thức theo chương trình học."],["Xem xét kế hoạch người thân đi cùng","Giúp gia đình hiểu rằng diện cha mẹ đi cùng có điều kiện riêng, bao gồm các yêu cầu bảo lãnh khi áp dụng."],["Lên kế hoạch chuyển đến","Sắp xếp danh sách tìm hiểu chỗ ở, thời gian đến, nhu cầu nhập học và các việc gia đình cần thực hiện."]],"outcome":"Lộ trình chuẩn bị học tập, checklist tuyển sinh, hướng dẫn hồ sơ giấy phép và nhiệm vụ rõ ràng cho gia đình."},"parent":{"headline":"Con học tại Singapore. Gia đình cũng cần một kế hoạch rõ ràng.","intro":"Gia đình cần hiểu liệu có diện người thân đi cùng phù hợp hay không và những thủ tục nào tách biệt với việc nhập học của trẻ.","items":[["Tìm hiểu hoàn cảnh gia đình","Xem xét tình trạng học tập và lưu trú của con, ai muốn đi cùng và kế hoạch sinh sống."],["Làm rõ điều kiện LTVP","Giải thích các điều kiện cần kiểm tra đối với cha mẹ hoặc ông bà đi cùng học sinh đủ điều kiện."],["Tìm hiểu yêu cầu bảo lãnh","Làm rõ khi nào cần người bảo lãnh địa phương đủ điều kiện và thông tin cần chuẩn bị."],["Chuẩn bị giấy tờ quan hệ gia đình","Sắp xếp hộ chiếu, giấy khai sinh, chứng minh quan hệ và những tài liệu được yêu cầu."],["Lập thứ tự các bước","Giúp hiểu bước nào liên quan đến nhập học, tình trạng lưu trú của trẻ, bảo lãnh và xét duyệt."],["Chuẩn bị cuộc sống tại Singapore","Nếu có trong phạm vi dịch vụ, lập checklist về chỗ ở, thời điểm đến và sinh hoạt của mẹ và con."]],"outcome":"Kế hoạch chuẩn bị người thân đi cùng, các điều kiện cần xác minh, checklist bảo lãnh và bước tiếp theo."},"family":{"headline":"Chuyển đến Singapore là kế hoạch của cả gia đình.","intro":"Một kế hoạch chuyển đến bao gồm diện lưu trú, trường học, nhà ở, ngân sách, thời gian và nhiều việc thực tế.","items":[["Xác định nhu cầu từng thành viên","Tìm hiểu mục đích chuyển đến, thời gian dự kiến và quan hệ gia đình liên quan đến từng người."],["Tìm hiểu diện lưu trú liên quan","Phân biệt các loại giấy phép gia đình cần xem xét và những điều kiện chính thức cần xác minh."],["Chuẩn bị giấy tờ","Lập danh sách giấy tờ nhân thân, quan hệ, tài chính và các tài liệu phù hợp với diện đăng ký."],["Xây dựng tiến độ chuyển đến","Sắp xếp các mốc chuẩn bị hồ sơ, nhập học, tìm nhà và đi lại."],["Lập danh sách ổn định cuộc sống","Chuẩn bị các vấn đề thực tế như nơi ở, đi lại, trường học và việc cần làm khi đến."],["Phân chia trách nhiệm rõ ràng","Ghi rõ phần việc của gia đình, người bảo lãnh, trường học và New Chapter trong phạm vi thỏa thuận."]],"outcome":"Lộ trình chuẩn bị cho gia đình, các câu hỏi về giấy phép, checklist hồ sơ, thời gian và kế hoạch chuyển đến."},"pr":{"headline":"Chuẩn bị hồ sơ PR Singapore có hệ thống và cẩn thận.","intro":"Thường trú nhân là một quyết định quan trọng. Chúng tôi hỗ trợ người đủ điều kiện tìm hiểu diện đăng ký với ICA, sắp xếp thông tin chính xác và chuẩn bị từng bước rõ ràng.","items":[["Tìm hiểu diện đủ điều kiện","Xem xét diện PR liên quan đến gia đình, việc làm, học tập hoặc đầu tư và điều kiện chính thức cần kiểm tra."],["Xem xét hoàn cảnh hồ sơ","Trao đổi về gia đình, học vấn, công việc, thời gian sinh sống và các thông tin liên quan."],["Lập danh sách giấy tờ","Xác định giấy tờ nhân thân, hộ tịch, học vấn, việc làm và tài liệu khác theo diện đăng ký."],["Sắp xếp thông tin nhất quán","Giúp kiểm tra mức độ đầy đủ, cách sắp xếp và sự thống nhất của thông tin giữa các giấy tờ, không thay đổi hoặc tạo ra dữ liệu."],["Chuẩn bị các bước nộp online","Giải thích quy trình, yêu cầu về file đính kèm và trách nhiệm nộp đơn, đóng phí của người đăng ký."],["Tìm hiểu giai đoạn sau khi nộp","Làm rõ cách nhận thông báo, bổ sung hồ sơ khi được yêu cầu và các bước theo dõi kết quả."]],"outcome":"Kế hoạch chuẩn bị PR theo diện đăng ký, checklist giấy tờ, tài liệu được sắp xếp và trách nhiệm nộp hồ sơ rõ ràng."},"citizenship":{"headline":"Chuẩn bị cẩn thận cho hành trình nhập quốc tịch Singapore.","intro":"Hồ sơ nhập quốc tịch liên quan đến điều kiện, hoàn cảnh gia đình, giấy tờ và những trách nhiệm quan trọng. Chúng tôi giúp tổ chức quá trình chuẩn bị phù hợp.","items":[["Xác định diện đăng ký","Tìm hiểu diện nhập quốc tịch liên quan và các điều kiện cần kiểm tra theo hướng dẫn ICA."],["Xem xét hoàn cảnh gia đình","Tìm hiểu thông tin của người đăng ký và các mối quan hệ vợ chồng, cha mẹ, con cái khi liên quan."],["Lập checklist tài liệu","Xác định giấy tờ nhân thân, hộ tịch, học vấn, việc làm và những hồ sơ hỗ trợ liên quan."],["Chuẩn bị thông tin chính xác","Hỗ trợ sắp xếp tài liệu và đối chiếu thông tin theo đúng quy trình, không tạo ra thông tin sai."],["Hiểu rõ nghĩa vụ liên quan","Làm rõ những trách nhiệm và yêu cầu chính thức có thể ảnh hưởng đến người đăng ký và gia đình."],["Nắm được các bước tiếp theo","Giải thích quá trình nộp đơn, thông báo và theo dõi hồ sơ để người đăng ký chủ động chuẩn bị."]],"outcome":"Lộ trình chuẩn bị quốc tịch, checklist giấy tờ và sự hiểu rõ về trách nhiệm cũng như các bước tiếp theo."},"documents":{"headline":"Giấy tờ quan trọng cần được sắp xếp rõ ràng từ đầu.","intro":"Mỗi trường học và thủ tục di trú yêu cầu tài liệu khác nhau. Chúng tôi giúp bạn nhận biết giấy tờ đã có, còn thiếu và có thể cần dịch thuật hay chứng nhận.","items":[["Xác định thủ tục cần chuẩn bị","Tìm hiểu mục đích tuyển sinh, giấy phép hoặc chuyển đến để xác định nhóm tài liệu liên quan."],["Lập danh mục giấy tờ","Chuẩn bị checklist các tài liệu bắt buộc và tài liệu hỗ trợ phù hợp."],["Xác định điểm cần bổ sung","Giúp phát hiện giấy tờ thiếu trang, hết hạn hoặc thông tin chưa đồng nhất cần làm rõ."],["Tìm hiểu yêu cầu dịch thuật","Giải thích khi nào có thể cần bản dịch hoặc chứng nhận và phối hợp đơn vị phù hợp nếu có trong dịch vụ."],["Sắp xếp tài liệu nộp hồ sơ","Hỗ trợ phân loại, đặt tên file và chuẩn bị bản sao theo yêu cầu thủ tục."],["Tổng hợp các việc còn lại","Lập danh sách tài liệu còn thiếu, người phụ trách và bước tiếp theo."]],"outcome":"Danh mục giấy tờ có tổ chức, checklist việc cần bổ sung và hỗ trợ dịch thuật hoặc chứng nhận trong phạm vi thống nhất."}}};
function serviceHelpDetail(key){
const d=SERVICE_DEPTH[lang][key],w=lang==="vi";
return '<section class="section v8-deep-help"><div class="container"><div class="v8-deep-head"><span class="eyebrow">'+(w?"HỖ TRỢ CHI TIẾT THEO DỊCH VỤ":"HOW NEW CHAPTER HELPS YOU")+'</span><h2 class="heading">'+esc(d.headline)+'</h2><p class="lead">'+esc(d.intro)+'</p></div><div class="v8-help-steps">'+d.items.map((item,i)=>'<article class="v8-help-step"><span class="v8-help-index">'+String(i+1).padStart(2,"0")+'</span><div><h3>'+esc(item[0])+'</h3><p>'+esc(item[1])+'</p></div></article>').join("")+'</div><div class="v8-help-outcome"><div><span class="eyebrow">'+(w?"KẾT QUẢ CHUẨN BỊ":"WHAT YOU TAKE AWAY")+'</span><h3>'+(w?"Một lộ trình rõ ràng cho bạn":"A clearer way forward")+'</h3><p>'+esc(d.outcome)+'</p></div><div>'+navLink("#/contact?service="+key,w?"Tìm hiểu tư vấn":"Explore consultation","btn primary")+'</div></div></div></section>';
}
function details(key){
const d=WORDS[lang],s=service(key);document.title=s.title+" | NEW CHAPTER";
return '<section class="detail-hero"><div class="container"><div class="crumb">'+navLink("#/",d.menu[0])+' / '+esc(s.title)+'</div><span class="eyebrow" style="color:#f1c6a9;margin-top:32px">'+esc(raw[key].tag)+'</span><h1>'+esc(s.title)+'</h1><p class="lead">'+esc(s.intro)+'</p></div></section>'+v8ServiceIntro(key)+v9ExpandedService(key)+v9Portfolio()+v9Journey()+v9ServiceClose(key)+'<section class="section v8-requirements"><div class="container v8-requirements-grid"><div><span class="eyebrow">'+(lang==="vi"?"TRƯỚC KHI BẮT ĐẦU":"BEFORE YOU BEGIN")+'</span><h2>'+esc(d.detailPrep)+'</h2>'+asList(s.prep)+'</div><div><h2>'+esc(d.detailKnow)+'</h2>'+asList(s.rules)+'</div></div></section>';
}
function legalPage(){const vi=lang==="vi";document.title=(vi?"Thông tin doanh nghiệp":"Company information")+" | NEW CHAPTER";return '<section class="detail-hero"><div class="container"><span class="eyebrow">NEW CHAPTER · SINGAPORE</span><h1>'+(vi?"Thông tin doanh nghiệp":"Company information")+'</h1></div></section><section class="section"><div class="container legal-page"><h2>'+(vi?"Đơn vị kinh doanh":"Business entity")+'</h2><p>NEW CHAPTER IMMIGRATION J&S PTE. LTD.<br>UEN 202439229W · Singapore</p><h2>'+(vi?"Giới thiệu dịch vụ":"About our services")+'</h2><p>'+(vi?"New Chapter là đơn vị tư vấn tư nhân. Quyết định tuyển sinh và cấp phép thuộc về cơ quan hoặc trường học có thẩm quyền.":"New Chapter provides private consultancy services. Schools and relevant authorities make their own admissions and application decisions.")+'</p><h2>'+(vi?"Thông tin hình ảnh":"Image credits")+'</h2><p>'+(vi?"Ảnh Trường Tiểu học Jurong:":"Jurong Primary School photograph:")+' <a href="https://commons.wikimedia.org/wiki/File:Jurong_Primary_School.jpg" target="_blank" rel="noopener noreferrer">Leejiaxin96 / Wikimedia Commons</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> ('+(vi?"đã cắt ảnh để phù hợp bố cục":"cropped for page layout")+'). '+(vi?"Ảnh phong cảnh khác: các tác giả trên Unsplash.":"Other location photography: Unsplash contributors.")+'</p></div></section>';}
function consult(){
const d=WORDS[lang];document.title=d.contact+" | NEW CHAPTER";
return '<section class="consult-hero"><div class="container consult-layout"><div><span class="eyebrow">'+esc(d.ctaTag)+'</span><h1 class="heading">'+esc(d.contactHeading)+'</h1><p class="lead">'+esc(d.contactDesc)+'</p><p class="cta-note">'+esc(d.noBooking)+'</p></div><div class="consult-box"><h2>'+esc(d.contactQuestion)+'</h2><form id="interest-form"><label for="interest">'+esc(d.contactPlaceholder)+'</label><select id="interest" required><option value="">'+esc(d.contactPlaceholder)+'</option>'+KEYS.map(k=>'<option value="'+k+'">'+esc(service(k).title)+'</option>').join("")+'</select><button type="submit" class="btn">'+esc(d.contactSubmit)+'</button><div id="interest-result" aria-live="polite"></div></form><p class="notice">'+esc(d.contactReminder)+'</p></div></div></section>';
}
function wirePlanner(){
const holder=byId("planner-options");if(!holder)return;
holder.addEventListener("click",ev=>{const button=ev.target.closest("button[data-plan]");if(!button)return;const key=button.getAttribute("data-plan");const index=KEYS.indexOf(key);if(index<0)return;holder.querySelectorAll("button").forEach(b=>{const active=b===button;b.classList.toggle("selected",active);b.setAttribute("aria-pressed",String(active))});
byId("plan-title").textContent=service(key).title;byId("plan-copy").textContent=WORDS[lang].planResult[index];byId("plan-link").href="#/service/"+key;byId("plan-contact").href="#/contact?service="+key});
}
function wireConsult(hash){
const f=byId("interest-form");if(!f)return;const selected=(hash.match(/[?&]service=([a-z]+)/)||[])[1];if(KEYS.includes(selected))byId("interest").value=selected;
f.addEventListener("submit",ev=>{ev.preventDefault();const key=byId("interest").value;if(!KEYS.includes(key))return;byId("interest-result").innerHTML='<div class="result">'+esc(WORDS[lang].contactResponse)+'<div style="margin-top:12px">'+navLink("#/service/"+key,WORDS[lang].contactLink,"text-link")+'</div></div>'});
}
function navigate(){shell();const hash=location.hash||"#/",key=hash.startsWith("#/service/")?hash.slice(10).split("?")[0]:"";const selected=(hash.match(/[?&]service=([a-z]+)/)||[])[1];byId("app").innerHTML=key==="student"?v10Student():KEYS.includes(key)?v10Details(key):hash.startsWith("#/legal")?legalPage():hash.startsWith("#/contact")?v10Contact(selected):hash.startsWith("#/faq")?v10Faq():hash.startsWith("#/about")?v10About():v10Homepage();const menu=byId("nav");menu.classList.remove("open");byId("menu-btn").setAttribute("aria-expanded","false");const anchors={"#/services":"services","#/why":"why","#/process":"process"};if(anchors[hash])byId(anchors[hash])?.scrollIntoView({block:"start",behavior:"instant"});else window.scrollTo({top:0,behavior:"instant"})}

for(const code of ["vi","en"]){byId("lang-"+code).addEventListener("click",()=>{if(lang===code)return;lang=code;try{window.localStorage.setItem("nc-lang",lang)}catch(e){}navigate()})}
byId("menu-btn").addEventListener("click",()=>{const opened=byId("nav").classList.toggle("open");byId("menu-btn").setAttribute("aria-expanded",String(opened))});
window.addEventListener("hashchange",navigate);navigate();
